-- Explicit actual available-stock dispatch batch sources, never retroactive inferred provenance.
CREATE TABLE inventory_batch_declarations(id TEXT PRIMARY KEY,outbound_id TEXT NOT NULL UNIQUE REFERENCES inventory_outbounds(id),store_id TEXT NOT NULL REFERENCES stores(id),sequence INTEGER NOT NULL CHECK(sequence>0),quantity INTEGER NOT NULL CHECK(typeof(quantity)='integer' AND quantity BETWEEN 1 AND 1000000),source_note TEXT NOT NULL,reason TEXT NOT NULL,created_at TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES users(id),UNIQUE(store_id,sequence));
CREATE TABLE inventory_batch_refs(id TEXT PRIMARY KEY,declaration_id TEXT NOT NULL REFERENCES inventory_batch_declarations(id),position INTEGER NOT NULL CHECK(position BETWEEN 1 AND 30),custody_id TEXT NOT NULL REFERENCES inventory_custody_roots(id),custody_version_id TEXT NOT NULL REFERENCES inventory_custody_versions(id),custody_event_id TEXT NOT NULL REFERENCES inventory_custody_events(id),receipt_id TEXT NOT NULL REFERENCES purchase_receipts(id),receipt_version_id TEXT NOT NULL REFERENCES purchase_receipt_versions(id),product_id TEXT NOT NULL REFERENCES retail_products(id),product_version INTEGER NOT NULL,unit TEXT NOT NULL,quantity INTEGER NOT NULL CHECK(typeof(quantity)='integer' AND quantity BETWEEN 1 AND 1000000),source_reference TEXT NOT NULL,note TEXT NOT NULL,UNIQUE(declaration_id,position),UNIQUE(declaration_id,custody_id),FOREIGN KEY(product_id,product_version) REFERENCES retail_product_versions(product_id,version));
CREATE TABLE inventory_batch_boundary(kind TEXT NOT NULL CHECK(kind IN('outbound','custody_version','quality_case')),record_id TEXT NOT NULL,PRIMARY KEY(kind,record_id));
INSERT INTO inventory_batch_boundary SELECT 'outbound',id FROM inventory_outbounds;
INSERT INTO inventory_batch_boundary SELECT 'custody_version',id FROM inventory_custody_versions;
INSERT INTO inventory_batch_boundary SELECT 'quality_case',id FROM purchase_quality_cases;
CREATE TABLE inventory_custody_version_batch_context(version_id TEXT PRIMARY KEY REFERENCES inventory_custody_versions(id),batch_sequence INTEGER NOT NULL CHECK(batch_sequence>=0));
INSERT INTO inventory_custody_version_batch_context SELECT id,0 FROM inventory_custody_versions;
CREATE TABLE purchase_quality_case_batch_context(case_id TEXT PRIMARY KEY REFERENCES purchase_quality_cases(id),batch_sequence INTEGER NOT NULL CHECK(batch_sequence>=0),product_return_revision INTEGER CHECK(product_return_revision>=0));
INSERT INTO purchase_quality_case_batch_context SELECT id,0,NULL FROM purchase_quality_cases;
CREATE TRIGGER inventory_batch_declaration_source BEFORE INSERT ON inventory_batch_declarations BEGIN
 SELECT CASE WHEN EXISTS(SELECT 1 FROM inventory_batch_boundary WHERE kind='outbound' AND record_id=NEW.outbound_id) OR NOT EXISTS(SELECT 1 FROM inventory_outbounds e WHERE e.id=NEW.outbound_id AND e.store_id=NEW.store_id AND e.source_mode='available' AND e.quantity=NEW.quantity AND e.outbound_revision=(SELECT max(outbound_revision) FROM inventory_outbounds WHERE product_id=e.product_id) AND e.created_at=NEW.created_at AND e.created_by=NEW.created_by) OR NEW.sequence<>coalesce((SELECT max(sequence)+1 FROM inventory_batch_declarations WHERE store_id=NEW.store_id),1) OR EXISTS(SELECT 1 FROM inventory_batch_declarations WHERE store_id=NEW.store_id AND created_at>NEW.created_at) OR NOT EXISTS(SELECT 1 FROM users u LEFT JOIN user_security s ON s.user_id=u.id WHERE u.id=NEW.created_by AND u.store_id=NEW.store_id AND u.role IN('manager','reception') AND u.active=1 AND coalesce(s.must_change_password,0)=0) OR length(NEW.created_at)<>24 OR strftime('%Y-%m-%dT%H:%M:%fZ',NEW.created_at) IS NOT NEW.created_at OR length(trim(NEW.source_note)) NOT BETWEEN 1 AND 2000 OR length(NEW.source_note)>2000 OR length(trim(NEW.reason)) NOT BETWEEN 1 AND 300 OR length(NEW.reason)>300 THEN RAISE(ABORT,'batch actual available outbound/actor/sequence') END;
END;
CREATE TRIGGER inventory_batch_ref_source BEFORE INSERT ON inventory_batch_refs BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM inventory_batch_declarations d JOIN inventory_outbounds e ON e.id=d.outbound_id JOIN inventory_custody_roots c ON c.id=NEW.custody_id JOIN inventory_custody_versions v ON v.id=NEW.custody_version_id AND v.root_id=c.id JOIN inventory_custody_current ce ON ce.root_id=c.id JOIN inventory_custody_dispatch_context dc ON dc.outbound_id=e.id JOIN purchase_receipts r ON r.id=c.receipt_id JOIN purchase_receipt_current rc ON rc.receipt_id=r.id JOIN retail_product_versions pv ON pv.product_id=r.product_id AND pv.version=r.product_version JOIN retail_product_versions ev ON ev.product_id=e.product_id AND ev.version=e.product_version JOIN inventory_dispatch_return_context rt ON rt.outbound_id=e.id WHERE d.id=NEW.declaration_id AND r.id=NEW.receipt_id AND r.product_id=NEW.product_id AND r.product_version=NEW.product_version AND pv.unit=NEW.unit AND pv.unit=ev.unit AND pv.category=ev.category AND e.product_id=r.product_id AND e.store_id=r.store_id AND c.store_id=e.store_id AND rc.status='posted' AND rc.version_id=v.receipt_version_id AND NEW.receipt_version_id=v.receipt_version_id AND ce.status='recorded' AND ce.action='observe' AND ce.id=NEW.custody_event_id AND ce.version_id=v.id AND ce.sequence<=dc.custody_sequence AND v.bucket='available' AND v.stock_sequence=e.basis_sequence AND v.outbound_revision+1=e.outbound_revision AND v.product_return_revision=rt.product_return_revision AND v.quality_sequence=coalesce((SELECT max(sequence) FROM purchase_quality_journal WHERE store_id=e.store_id),0) AND v.created_at<=e.created_at AND NEW.quantity<=v.quantity-coalesce((SELECT sum(quantity) FROM inventory_batch_refs WHERE custody_version_id=v.id),0) AND NEW.quantity<=r.bound_quantity-coalesce((SELECT sum(quantity) FROM supplier_return_handoffs WHERE receipt_id=r.id),0)-coalesce((SELECT sum(b.quantity) FROM inventory_batch_refs b WHERE b.receipt_id=r.id),0)-coalesce((SELECT sum(quantity) FROM purchase_quality_holds WHERE receipt_id=r.id),0)) OR NEW.position<>coalesce((SELECT max(position)+1 FROM inventory_batch_refs WHERE declaration_id=NEW.declaration_id),1) OR NEW.quantity+coalesce((SELECT sum(quantity) FROM inventory_batch_refs WHERE declaration_id=NEW.declaration_id),0)>(SELECT quantity FROM inventory_batch_declarations WHERE id=NEW.declaration_id) OR length(trim(NEW.source_reference)) NOT BETWEEN 1 AND 1000 OR length(NEW.source_reference)>1000 OR length(trim(NEW.note)) NOT BETWEEN 1 AND 2000 OR length(NEW.note)>2000 THEN RAISE(ABORT,'batch fixed original observation/unit/quantity/source') END;
END;
CREATE TRIGGER inventory_batch_custody_capacity BEFORE INSERT ON inventory_custody_versions WHEN EXISTS(SELECT 1 FROM inventory_custody_roots c JOIN purchase_receipts r ON r.id=c.receipt_id WHERE c.id=NEW.root_id AND NEW.quantity>r.bound_quantity-coalesce((SELECT sum(quantity) FROM supplier_return_handoffs WHERE receipt_id=r.id),0)-coalesce((SELECT sum(quantity) FROM inventory_batch_refs WHERE receipt_id=r.id),0)-CASE NEW.bucket WHEN 'available' THEN coalesce((SELECT sum(quantity) FROM purchase_quality_holds WHERE receipt_id=r.id),0) ELSE 0 END) BEGIN SELECT RAISE(ABORT,'batch known sold original cannot be observed again');END;
CREATE TRIGGER inventory_batch_quality_capacity BEFORE INSERT ON purchase_quality_cases WHEN EXISTS(SELECT 1 FROM purchase_receipts r WHERE r.id=NEW.receipt_id AND NEW.quantity>r.bound_quantity-coalesce((SELECT sum(quantity) FROM supplier_return_handoffs WHERE receipt_id=r.id),0)-coalesce((SELECT sum(quantity) FROM inventory_batch_refs WHERE receipt_id=r.id),0)-coalesce((SELECT sum(quantity) FROM purchase_quality_holds WHERE receipt_id=r.id),0)) BEGIN SELECT RAISE(ABORT,'batch known sold original cannot enter quality custody');END;
CREATE TRIGGER inventory_custody_batch_capture AFTER INSERT ON inventory_custody_versions BEGIN INSERT INTO inventory_custody_version_batch_context VALUES(NEW.id,coalesce((SELECT max(sequence) FROM inventory_batch_declarations WHERE store_id=NEW.store_id),0));END;
CREATE TRIGGER inventory_custody_batch_context_source BEFORE INSERT ON inventory_custody_version_batch_context WHEN NOT EXISTS(SELECT 1 FROM inventory_custody_versions v WHERE v.id=NEW.version_id AND NEW.batch_sequence=coalesce((SELECT max(sequence) FROM inventory_batch_declarations WHERE store_id=v.store_id),0)) BEGIN SELECT RAISE(ABORT,'batch original custody prefix');END;
CREATE TRIGGER purchase_quality_batch_capture AFTER INSERT ON purchase_quality_cases BEGIN INSERT INTO purchase_quality_case_batch_context VALUES(NEW.id,coalesce((SELECT max(sequence) FROM inventory_batch_declarations WHERE store_id=NEW.store_id),0),coalesce((SELECT max(h.product_revision) FROM supplier_return_handoffs h JOIN purchase_receipts r ON r.product_id=h.product_id WHERE r.id=NEW.receipt_id),0));END;
CREATE TRIGGER purchase_quality_batch_context_source BEFORE INSERT ON purchase_quality_case_batch_context WHEN NOT EXISTS(SELECT 1 FROM purchase_quality_cases c JOIN purchase_receipts r ON r.id=c.receipt_id WHERE c.id=NEW.case_id AND NEW.batch_sequence=coalesce((SELECT max(sequence) FROM inventory_batch_declarations WHERE store_id=c.store_id),0) AND NEW.product_return_revision IS coalesce((SELECT max(product_revision) FROM supplier_return_handoffs WHERE product_id=r.product_id),0)) BEGIN SELECT RAISE(ABORT,'batch original quality prefix');END;
CREATE TRIGGER inventory_batch_declarations_no_update BEFORE UPDATE ON inventory_batch_declarations BEGIN SELECT RAISE(ABORT,'batch immutable');END;
CREATE TRIGGER inventory_batch_declarations_no_delete BEFORE DELETE ON inventory_batch_declarations BEGIN SELECT RAISE(ABORT,'batch immutable');END;
CREATE TRIGGER inventory_batch_refs_no_update BEFORE UPDATE ON inventory_batch_refs BEGIN SELECT RAISE(ABORT,'batch immutable');END;
CREATE TRIGGER inventory_batch_refs_no_delete BEFORE DELETE ON inventory_batch_refs BEGIN SELECT RAISE(ABORT,'batch immutable');END;
CREATE TRIGGER inventory_batch_boundary_no_update BEFORE UPDATE ON inventory_batch_boundary BEGIN SELECT RAISE(ABORT,'batch immutable');END;
CREATE TRIGGER inventory_batch_boundary_no_delete BEFORE DELETE ON inventory_batch_boundary BEGIN SELECT RAISE(ABORT,'batch immutable');END;
CREATE TRIGGER inventory_custody_version_batch_context_no_update BEFORE UPDATE ON inventory_custody_version_batch_context BEGIN SELECT RAISE(ABORT,'batch immutable');END;
CREATE TRIGGER inventory_custody_version_batch_context_no_delete BEFORE DELETE ON inventory_custody_version_batch_context BEGIN SELECT RAISE(ABORT,'batch immutable');END;
CREATE TRIGGER purchase_quality_case_batch_context_no_update BEFORE UPDATE ON purchase_quality_case_batch_context BEGIN SELECT RAISE(ABORT,'batch immutable');END;
CREATE TRIGGER purchase_quality_case_batch_context_no_delete BEFORE DELETE ON purchase_quality_case_batch_context BEGIN SELECT RAISE(ABORT,'batch immutable');END;
CREATE TRIGGER inventory_batch_boundary_no_insert BEFORE INSERT ON inventory_batch_boundary BEGIN SELECT RAISE(ABORT,'batch immutable boundary');END;
ALTER TABLE inventory_batch_declarations ADD COLUMN receipt_sequence INTEGER NOT NULL CHECK(receipt_sequence>=0);
ALTER TABLE inventory_batch_declarations ADD COLUMN quality_sequence INTEGER NOT NULL CHECK(quality_sequence>=0);
CREATE TRIGGER inventory_batch_original_prefix BEFORE INSERT ON inventory_batch_declarations WHEN NEW.receipt_sequence<>coalesce((SELECT max(sequence) FROM purchase_receiving_journal WHERE store_id=NEW.store_id),0) OR NEW.quality_sequence<>coalesce((SELECT max(sequence) FROM purchase_quality_journal WHERE store_id=NEW.store_id),0) OR EXISTS(SELECT 1 FROM purchase_receiving_journal WHERE store_id=NEW.store_id AND created_at>NEW.created_at) OR EXISTS(SELECT 1 FROM purchase_quality_journal WHERE store_id=NEW.store_id AND created_at>NEW.created_at) BEGIN SELECT RAISE(ABORT,'batch original receipt/quality prefix/time');END;
CREATE TABLE inventory_batch_receipt_context(receipt_event_id TEXT PRIMARY KEY REFERENCES purchase_receipt_events(id),batch_sequence INTEGER NOT NULL CHECK(batch_sequence>=0));
INSERT INTO inventory_batch_receipt_context SELECT id,0 FROM purchase_receipt_events;
CREATE TRIGGER inventory_batch_receipt_capture AFTER INSERT ON purchase_receipt_events BEGIN INSERT INTO inventory_batch_receipt_context VALUES(NEW.id,coalesce((SELECT max(sequence) FROM inventory_batch_declarations WHERE store_id=NEW.store_id),0));END;
CREATE TRIGGER inventory_batch_receipt_context_source BEFORE INSERT ON inventory_batch_receipt_context WHEN NOT EXISTS(SELECT 1 FROM purchase_receipt_events e WHERE e.id=NEW.receipt_event_id AND NEW.batch_sequence=coalesce((SELECT max(sequence) FROM inventory_batch_declarations WHERE store_id=e.store_id),0)) BEGIN SELECT RAISE(ABORT,'batch original receiving context');END;
CREATE TRIGGER inventory_batch_receipt_time BEFORE INSERT ON purchase_receipt_events WHEN EXISTS(SELECT 1 FROM inventory_batch_declarations WHERE store_id=NEW.store_id AND created_at>NEW.created_at) BEGIN SELECT RAISE(ABORT,'batch original receipt chronology');END;
CREATE TABLE inventory_batch_quality_context(quality_event_id TEXT PRIMARY KEY REFERENCES purchase_quality_events(id),batch_sequence INTEGER NOT NULL CHECK(batch_sequence>=0));
INSERT INTO inventory_batch_quality_context SELECT id,0 FROM purchase_quality_events;
CREATE TRIGGER inventory_batch_quality_capture AFTER INSERT ON purchase_quality_events BEGIN INSERT INTO inventory_batch_quality_context VALUES(NEW.id,coalesce((SELECT max(sequence) FROM inventory_batch_declarations WHERE store_id=NEW.store_id),0));END;
CREATE TRIGGER inventory_batch_quality_context_source BEFORE INSERT ON inventory_batch_quality_context WHEN NOT EXISTS(SELECT 1 FROM purchase_quality_events e WHERE e.id=NEW.quality_event_id AND NEW.batch_sequence=coalesce((SELECT max(sequence) FROM inventory_batch_declarations WHERE store_id=e.store_id),0)) BEGIN SELECT RAISE(ABORT,'batch original quality event context');END;
CREATE TRIGGER inventory_batch_quality_time BEFORE INSERT ON purchase_quality_events WHEN EXISTS(SELECT 1 FROM inventory_batch_declarations WHERE store_id=NEW.store_id AND created_at>NEW.created_at) BEGIN SELECT RAISE(ABORT,'batch original quality event chronology');END;
CREATE TRIGGER inventory_batch_receipt_context_no_update BEFORE UPDATE ON inventory_batch_receipt_context BEGIN SELECT RAISE(ABORT,'batch immutable');END;
CREATE TRIGGER inventory_batch_receipt_context_no_delete BEFORE DELETE ON inventory_batch_receipt_context BEGIN SELECT RAISE(ABORT,'batch immutable');END;
CREATE TRIGGER inventory_batch_quality_context_no_update BEFORE UPDATE ON inventory_batch_quality_context BEGIN SELECT RAISE(ABORT,'batch immutable');END;
CREATE TRIGGER inventory_batch_quality_context_no_delete BEFORE DELETE ON inventory_batch_quality_context BEGIN SELECT RAISE(ABORT,'batch immutable');END;
